import numpy as np
from scipy import sparse
from reference import Task
import time
import cProfile

task = Task()
problem = task.generate_problem(1000, 1)
A = problem["matrix"]
k = problem["k"]
N = A.shape[0]
v0 = np.ones(N, dtype=A.dtype)

def run_orig():
    sparse.linalg.eigs(A, k=k, v0=v0, maxiter=N * 200, ncv=20)

class FastOp(sparse.linalg.LinearOperator):
    def __init__(self, A):
        self.A = A
        self.shape = A.shape
        self.dtype = A.dtype
    def _matvec(self, x):
        return self.A.dot(x)
    def _matmat(self, x):
        return self.A.dot(x)

def run_fast():
    op = FastOp(A)
    sparse.linalg.eigs(op, k=k, v0=v0, maxiter=N * 200, ncv=20)

t0 = time.time()
for _ in range(5): run_orig()
print("Orig:", time.time() - t0)

t0 = time.time()
for _ in range(5): run_fast()
print("Fast:", time.time() - t0)
